describe('Itemised Receipt After Checkout', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.clearCookies();
    cy.clearLocalStorage();
  });

  it('should display itemised receipt with all purchased items after successful checkout', () => {
    // Add items to cart
    cy.get('[data-testid="product-item"]').first().click();
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.get('[data-testid="continue-shopping-btn"]').click();

    cy.get('[data-testid="product-item"]').eq(1).click();
    cy.get('[data-testid="add-to-cart-btn"]').click();

    // Navigate to checkout
    cy.get('[data-testid="cart-icon"]').click();
    cy.get('[data-testid="checkout-btn"]').click();

    // Fill in checkout form
    cy.get('[data-testid="email-input"]').type('test@example.com');
    cy.get('[data-testid="first-name-input"]').type('John');
    cy.get('[data-testid="last-name-input"]').type('Doe');
    cy.get('[data-testid="address-input"]').type('123 Main St');
    cy.get('[data-testid="city-input"]').type('New York');
    cy.get('[data-testid="zip-input"]').type('10001');

    // Fill payment details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Complete purchase
    cy.get('[data-testid="place-order-btn"]').click();

    // Verify receipt page is displayed
    cy.get('[data-testid="receipt-container"]').should('be.visible');
    cy.get('[data-testid="receipt-title"]').should('contain', 'Order Confirmation');

    // Verify itemised list
    cy.get('[data-testid="receipt-items"]').should('exist');
    cy.get('[data-testid="receipt-item-row"]').should('have.length', 2);

    // Verify each item shows name, quantity, and price
    cy.get('[data-testid="receipt-item-row"]').each(($item) => {
      cy.wrap($item).find('[data-testid="item-name"]').should('not.be.empty');
      cy.wrap($item).find('[data-testid="item-quantity"]').should('not.be.empty');
      cy.wrap($item).find('[data-testid="item-price"]').should('not.be.empty');
    });

    // Verify totals section
    cy.get('[data-testid="subtotal"]').should('be.visible');
    cy.get('[data-testid="tax"]').should('be.visible');
    cy.get('[data-testid="total"]').should('be.visible');

    // Verify order number and date
    cy.get('[data-testid="order-number"]').should('not.be.empty');
    cy.get('[data-testid="order-date"]').should('not.be.empty');
  });

  it('should display receipt with single item and correct calculations', () => {
    // Add single item to cart
    cy.get('[data-testid="product-item"]').first().click();
    cy.get('[data-testid="product-price"]').then(($price) => {
      const itemPrice = parseFloat($price.text().replace('$', ''));
      cy.wrap(itemPrice).as('expectedPrice');
    });
    cy.get('[data-testid="add-to-cart-btn"]').click();

    // Navigate to checkout
    cy.get('[data-testid="cart-icon"]').click();
    cy.get('[data-testid="checkout-btn"]').click();

    // Fill checkout form
    cy.get('[data-testid="email-input"]').type('single@example.com');
    cy.get('[data-testid="first-name-input"]').type('Jane');
    cy.get('[data-testid="last-name-input"]').type('Smith');
    cy.get('[data-testid="address-input"]').type('456 Oak Ave');
    cy.get('[data-testid="city-input"]').type('Los Angeles');
    cy.get('[data-testid="zip-input"]').type('90001');

    // Fill payment details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Complete purchase
    cy.get('[data-testid="place-order-btn"]').click();

    // Verify receipt
    cy.get('[data-testid="receipt-container"]').should('be.visible');
    cy.get('[data-testid="receipt-item-row"]').should('have.length', 1);

    // Verify item details
    cy.get('[data-testid="receipt-item-row"]').within(() => {
      cy.get('[data-testid="item-quantity"]').should('contain', '1');
    });

    // Verify calculations are correct
    cy.get('@expectedPrice').then((price) => {
      cy.get('[data-testid="subtotal"]').should('contain', price.toFixed(2));
    });

    // Verify total is greater than subtotal (includes tax)
    cy.get('[data-testid="subtotal"]').then(($subtotal) => {
      const subtotal = parseFloat($subtotal.text().replace('$', ''));
      cy.get('[data-testid="total"]').then(($total) => {
        const total = parseFloat($total.text().replace('$', ''));
        expect(total).to.be.greaterThan(subtotal);
      });
    });
  });
});
